// Status codes returned by this interface. RemoteFW methods return a Win32 error
// code ([MS-ERREF] 2.2, transmitted as the DWORD return value); ERROR_SUCCESS (0)
// indicates success. These are the codes [MS-FASP] documents most methods returning.
const (
	StatusSuccess           uint32 = 0x00000000 // ERROR_SUCCESS
	ErrorFileNotFound       uint32 = 0x00000002 // ERROR_FILE_NOT_FOUND
	ErrorAccessDenied       uint32 = 0x00000005 // ERROR_ACCESS_DENIED
	ErrorInvalidHandle      uint32 = 0x00000006 // ERROR_INVALID_HANDLE
	ErrorNotEnoughMemory    uint32 = 0x00000008 // ERROR_NOT_ENOUGH_MEMORY
	ErrorInvalidData        uint32 = 0x0000000D // ERROR_INVALID_DATA
	ErrorFileExists         uint32 = 0x00000050 // ERROR_FILE_EXISTS
	ErrorInvalidParameter   uint32 = 0x00000057 // ERROR_INVALID_PARAMETER
	ErrorInsufficientBuffer uint32 = 0x0000007A // ERROR_INSUFFICIENT_BUFFER
	ErrorAlreadyExists      uint32 = 0x000000B7 // ERROR_ALREADY_EXISTS
	ErrorNoMoreItems        uint32 = 0x00000103 // ERROR_NO_MORE_ITEMS
	ErrorNotFound           uint32 = 0x00000490 // ERROR_NOT_FOUND
)

// SyntaxID returns the RemoteFW abstract syntax identifier:
// 6b5bdd1e-528c-422c-af8c-a4079be4fe48, version 1.0.
